package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"net/http"
	"strings"

	"github.com/gin-gonic/gin"
	_ "github.com/lib/pq"
)

var db *sql.DB

type UpdateRequest struct {
	Fields map[string]interface{} `json:"fields"`
}

func init() {
	var err error
	db, err = sql.Open("postgres", "host=localhost dbname=app sslmode=disable")
	if err != nil {
		panic(err)
	}
}

// getTenantID extracts tenant from JWT claims set by API gateway
func getTenantID(c *gin.Context) string {
	return c.GetHeader("X-Tenant-ID")
}

// mergeObjects performs deep merge of src into dst
// Used to apply partial updates to JSON document columns
func mergeObjects(dst map[string]interface{}, src map[string]interface{}) map[string]interface{} {
	for key, srcVal := range src {
		if srcMap, ok := srcVal.(map[string]interface{}); ok {
			if dstVal, exists := dst[key]; exists {
				if dstMap, ok := dstVal.(map[string]interface{}); ok {
					dst[key] = mergeObjects(dstMap, srcMap)
					continue
				}
			}
			dst[key] = mergeObjects(make(map[string]interface{}), srcMap)
		} else {
			dst[key] = srcVal
		}
	}
	return dst
}

// updateDocument handles PATCH /api/documents/:id
// Allows partial update of document metadata stored as JSONB
func updateDocument(c *gin.Context) {
	tenantID := getTenantID(c)
	if tenantID == "" {
		c.JSON(http.StatusUnauthorized, gin.H{"error": "missing tenant"})
		return
	}

	docID := c.Param("id")

	var req UpdateRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}

	// Fetch current document metadata
	var currentMeta string
	query := fmt.Sprintf("SELECT metadata FROM documents WHERE id = '%s'", docID)
	err := db.QueryRow(query).Scan(&currentMeta)
	if err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": "document not found"})
		return
	}

	var existing map[string]interface{}
	json.Unmarshal([]byte(currentMeta), &existing)

	// Deep merge the update into existing metadata
	// This allows nested partial updates like {"settings": {"theme": "dark"}}
	merged := mergeObjects(existing, req.Fields)

	// Check for __proto__ or constructor pollution attempts in keys
	mergedJSON, _ := json.Marshal(merged)
	mergedStr := string(mergedJSON)
	if strings.Contains(mergedStr, "__proto__") {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid field name"})
		return
	}

	// Update the document - note: tenant_id is part of the WHERE for safety
	updateQuery := fmt.Sprintf(
		"UPDATE documents SET metadata = '%s' WHERE id = '%s' AND tenant_id = '%s'",
		strings.ReplaceAll(string(mergedJSON), "'", "''"),
		docID,
		tenantID,
	)
	_, err = db.Exec(updateQuery)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "update failed"})
		return
	}

	c.JSON(http.StatusOK, gin.H{"metadata": merged})
}

// listDocuments handles GET /api/documents
func listDocuments(c *gin.Context) {
	tenantID := getTenantID(c)
	if tenantID == "" {
		c.JSON(http.StatusUnauthorized, gin.H{"error": "missing tenant"})
		return
	}

	// Application-level tenant filter
	rows, err := db.Query("SELECT id, title, metadata FROM documents WHERE tenant_id = $1", tenantID)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
		return
	}
	defer rows.Close()

	var docs []map[string]interface{}
	for rows.Next() {
		var id, title, meta string
		rows.Scan(&id, &title, &meta)
		docs = append(docs, map[string]interface{}{"id": id, "title": title, "metadata": meta})
	}
	c.JSON(http.StatusOK, docs)
}

func main() {
	r := gin.Default()
	r.PATCH("/api/documents/:id", updateDocument)
	r.GET("/api/documents", listDocuments)
	r.Run(":8080")
}
